import { COMPANIES } from './domain.js';
import { priceLevel } from './pricing.js';
import { escape,on,notify,pageHead,values,badge,dateTime } from './ui.js';

export async function render(ctx,view) {
  if(!ctx.isAdmin()){throw new Error('Admin access is required.');}
  const status=await ctx.read('/status'),current=status.settings,s=current.data;
  let imports=[];if(s.enabled){imports=(await ctx.read('/imports')).items;}
  const companyFields=[['name','Company name'],['address','Company address'],['subsidiaryId','NetSuite subsidiary ID'],['formId','Estimate form ID'],['currencyId','CAD currency ID'],['taxCodeId','Tax code ID'],['closedStatusId','Closed estimate status ID'],['openStatusId','Open estimate status ID'],['locationId','Default location ID']];
  view.innerHTML=pageHead('Field Sales settings','Configure access, City imports, quote profiles, and integration readiness.')+`<form id="settings-form" class="stack"><section class="panel panel-pad stack"><h2>Module controls</h2><label class="check"><input type="checkbox" name="enabled" ${s.enabled?'checked':''}>Enable Field Sales</label><label class="check"><input type="checkbox" name="importsEnabled" ${s.importsEnabled?'checked':''}>Refresh City data automatically</label><label class="check"><input type="checkbox" name="postingEnabled" ${s.postingEnabled?'checked':''}>Allow quote publication</label><div class="banner">${status.postingAvailable?'The server posting gate is enabled. Validate company mappings in a NetSuite sandbox before production use.':'The server posting gate is disabled. Drafts and PDFs work independently of NetSuite publication.'}</div><small>Grant the dedicated Field Sales authority through Admin → Accounts. Jobsites and quotes are shared; routes belong to the assigned rep.</small><a href="/admin/accounts">Manage staff accounts ↗</a></section><div class="grid two">${COMPANIES.map(c=>`<section class="panel panel-pad stack"><h2>${c} quotes</h2><small>Item pricing: NetSuite ${priceLevel(c)} in CAD</small>${companyFields.map(([key,label])=>`<label>${label}<input name="${c}.${key}" value="${escape(s.companies[c][key])}"></label>`).join('')}<label>Tax rate (%)<input name="${c}.taxPercent" inputmode="decimal" value="${s.companies[c].taxBps/100}" required></label><label>PDF terms<textarea name="${c}.terms">${escape(s.companies[c].terms)}</textarea></label></section>`).join('')}</div><section class="panel panel-pad stack"><h2>Visit outcomes</h2><label>One result per line<textarea name="outcomes" rows="8">${escape((s.outcomes||status.outcomes).join('\n'))}</textarea></label></section><div class="actions"><button class="primary">Save settings</button><span class="muted" style="font-size:12px">New quote revisions use the current tax policy. Previous PDFs keep their saved policy.</span></div></form>${s.enabled?`<section class="panel" style="margin-top:24px"><div class="panel-title"><h2>City data & catalogs</h2><button id="refresh-status" class="small">Refresh status</button></div><div class="panel-pad stack"><p class="muted" style="font-size:12px">Imports are staged before replacing the previous complete snapshot. Your notes, priorities, visits and manually adjusted details are retained.</p><div class="actions">${[['planning','Planning applications'],['permits','Active permits'],['postal','Postal areas'],['addresses','Address coordinates']].map(([source,label])=>`<button class="small" data-import="${source}">Refresh ${label}</button>`).join('')}<button id="refresh-catalog" class="small">Refresh item catalog</button></div><small>Automatic refresh: daily planning, permits and postal areas; weekly address coordinates. All active permit ages are retained. Postal areas are three-character FSAs.</small><div class="overflow"><table><thead><tr><th>Source</th><th>State</th><th>Records</th><th>Started</th><th>Detail</th></tr></thead><tbody>${imports.map(i=>`<tr><td>${escape(i.source)}</td><td>${badge(i.state,i.state==='failed'?'red':'')}</td><td>${i.record_count}</td><td>${escape(dateTime(i.started_at))}</td><td>${escape(i.error)}</td></tr>`).join('')}</tbody></table></div><a href="https://www.toronto.ca/city-government/planning-development/application-information-centre/" target="_blank" rel="noopener">Toronto Application Information Centre ↗</a></div></section>`:''}`;
  on('#settings-form','submit',async(e,f)=>{e.preventDefault();const v=values(f),data={...s,enabled:Boolean(v.enabled),importsEnabled:Boolean(v.importsEnabled),postingEnabled:Boolean(v.postingEnabled),outcomes:v.outcomes.split('\n').map(outcome=>outcome.trim()).filter(Boolean),companies:structuredClone(s.companies)};for(const c of COMPANIES){for(const [key] of companyFields){data.companies[c][key]=v[`${c}.${key}`];}data.companies[c].terms=v[`${c}.terms`];data.companies[c].taxBps=Math.round(Number(v[`${c}.taxPercent`])*100);}const updated=await ctx.api('/settings',{revision:current.revision,data},'PUT');ctx.state.settings=updated.data;notify('Settings saved.');await render(ctx,view);},view);
  on('[data-import]','click',async(e,b)=>{await ctx.api(`/imports/${b.dataset.import}`,{});notify('Import started. Refresh status to see progress.');setTimeout(()=>void render(ctx,view),1500);},view);on('#refresh-catalog','click',async()=>{const result=await ctx.api('/catalog/refresh',{});notify(`${result.count} active catalog items refreshed.`);},view);on('#refresh-status','click',()=>render(ctx,view),view);
}

