const CACHE='mbbs-field-sales-shell-v8';
const SHELL=['/field-sales/','/field-sales/index.html','/field-sales/app.js','/field-sales/ui.js','/field-sales/planner.js','/field-sales/planner-data.js','/field-sales/lead-policy.js','/field-sales/pricing.js','/field-sales/item-autocomplete.js','/field-sales/quotes.js','/field-sales/visiting.js','/field-sales/settings.js','/field-sales/offline.js','/field-sales/domain.js','/field-sales/styles.css','/field-sales/icon.svg','/field-sales/manifest.webmanifest'];
