import { $,escape,on,notify,modal,money,badge,empty,pageHead,values,download } from './ui.js';
import { bindItemSearch,itemSearchMarkup } from './item-autocomplete.js';
import { suggestedRate,sameDecimal } from './pricing.js';
import { calculateQuote } from './domain.js';
let selectedId=null,newSite=null,quote=null,edit=null,ctx=null,view=null,pendingEntry=null,resolving=false;
export function choosePending(entry){pendingEntry=entry;}
export function chooseJobsite(site){newSite=site;selectedId=null;}
export function chooseQuote(id){selectedId=id;newSite=null;}

export async function render(context,target) {
  ctx=context;view=target;
  if(pendingEntry){
    const entry=pendingEntry;pendingEntry=null;
    const latest=await ctx.load('quote',entry.payload.id);let remote=null;
