    const status=await ctx.api('/status');ctx.state.settings=status.settings.data;
    quote=remote;edit={...latest.snapshot,id:latest.id,jobsiteId:latest.jobsite_id,revision:remote?.revision||0};resolving=true;
    await editor();return;
  }
  resolving=false;

  if(newSite){const site=newSite;newSite=null;return createQuote(site);}
  if(selectedId){const id=selectedId;selectedId=null;return openQuote(id);}
  const data=await ctx.list('quote'),drafts=(await ctx.state.workspace.records('editquote:')).filter(q=>q?.id);
  view.innerHTML=pageHead('Jobsite quotes','One quote for the customer. Separate MBBS, MBR and MBT estimates in NetSuite.','<button id="new-quote" class="primary">＋ New quote</button>')+`${drafts.length?`<div class="panel panel-pad stack" style="margin-bottom:16px"><h3>Draft edits saved on this device</h3>${drafts.map(d=>`<button data-draft="${d.id}">${escape(d.customerName||'New prospect')} · ${escape(d.jobsite?.address||'Draft quote')}</button>`).join('')}</div>`:''}<div class="panel overflow"><table><thead><tr><th>Quote</th><th>Customer / prospect</th><th>Jobsite</th><th>Total CAD</th><th>Revision</th><th></th></tr></thead><tbody>${data.items.map(q=>`<tr><td>${escape(q.number||`FS-${String(q.quote_number).padStart(6,'0')}`)}</td><td>${escape(q.customer_name||q.snapshot?.customerName)}</td><td>${escape(q.jobsite?.address||q.snapshot?.jobsite?.address)}</td><td>${money(q.total_minor||q.snapshot?.totalMinor)}</td><td>${q.revision}${q.published_revision===q.revision?' · Published':''}</td><td><button class="small" data-open-quote="${q.id}">Open</button></td></tr>`).join('')}</tbody></table>${data.items.length?'':empty('Create a quote from a jobsite, or choose New quote.')}</div>`;
  on('#new-quote','click',pickJobsite,view);on('[data-open-quote]','click',(e,b)=>openQuote(b.dataset.openQuote),view);on('[data-draft]','click',async(e,b)=>{edit=await ctx.state.workspace.get(`editquote:${b.dataset.draft}`);quote=edit.revision?await ctx.load('quote',edit.id):null;await editor();},view);
}
async function pickJobsite() {
  const el=modal('Choose a jobsite',`<form id="quote-site-search" class="field-row"><label>Jobsite address or name<input name="search" required placeholder="Search jobsites"></label><button>Search</button></form><div id="quote-site-results" class="catalog-results"></div>`);
  on('#quote-site-search','submit',async(event,f)=>{event.preventDefault();const term=values(f).search;let items;try{items=(await ctx.list('jobsite',`/jobsites?source=all&search=${encodeURIComponent(term)}`)).items;}catch{items=(await ctx.state.workspace.records('jobsite:')).filter(s=>`${s.name} ${s.address}`.toLowerCase().includes(term.toLowerCase()));}$('#quote-site-results').innerHTML=items.map(s=>`<div class="catalog-item"><span>${escape(s.address)}</span><button data-quote-site="${s.id}" class="small">Select</button></div>`).join('')||empty('No matching jobsite. Add one in Prospects or Visiting.');on('[data-quote-site]','click',async(e,b)=>{el.close();await createQuote(items.find(s=>s.id===b.dataset.quoteSite));},el);},el);
}
async function createQuote(site) {
  quote=null;edit={id:crypto.randomUUID(),revision:0,jobsiteId:site.id,jobsite:{id:site.id,address:site.address},customerName:'',customerId:'',contact:'',email:'',validUntil:'',note:'',currency:'CAD',lines:[]};
  await persistEdit();await editor();
}
async function openQuote(id,revision) {
  quote=revision?await ctx.api(`/quotes/${id}?revision=${revision}`):await ctx.load('quote',id);
  const draft=revision?null:await ctx.state.workspace.get(`editquote:${id}`);
  edit=draft||{...quote.snapshot,id:quote.id,jobsiteId:quote.jobsite_id,revision:quote.revision,lines:structuredClone(quote.snapshot.lines)};
