    const root=$(`[data-line="${line.id}"]`);if(!root){continue;}
    const previousQuantity=line.quantity,previousRate=line.unitRate;
    for(const name of ['quantity','unitRate','description']){line[name]=$(`[name=${name}]`,root)?.value??line[name];}
    if(previousQuantity!==line.quantity&&!line.overrideReason&&line.catalogPrice){
      const item={company:line.company,unit_rate:line.catalogPrice.unitRate,pricing:line.catalogPrice.pricing};
      try{if(sameDecimal(previousRate,suggestedRate(item,previousQuantity))&&sameDecimal(previousRate,line.unitRate)){line.unitRate=suggestedRate(item,line.quantity)??'';$('[name=unitRate]',root).value=line.unitRate;}}catch{/* Totals display invalid intermediate quantities while typing. */}
    }
  }
}
function totals() {
  for(const line of edit.lines){
    const output=$(`[data-line="${line.id}"] [data-line-subtotal]`,view);
    if(!output){continue;}
    try{output.textContent=money(calculateQuote({currency:edit.currency,lines:[line]},ctx.state.settings.companies).lines[0].amountMinor);}
    catch{output.textContent='—';}
  }
  try {
    const calculated=calculateQuote(edit,ctx.state.settings.companies);
    $('#quote-totals').innerHTML=`<h3>Quote total</h3><small>CAD · revision totals</small>${Object.entries(calculated.companies).map(([company,c])=>`<hr class="divider"><div class="row"><strong>${company}</strong>${badge(`${c.taxBps/100}% tax`)}</div><div class="total-row"><span>Subtotal</span><span>${money(c.subtotalMinor)}</span></div><div class="total-row"><span>Tax</span><span>${money(c.taxMinor)}</span></div><div class="total-row"><strong>${company} total</strong><strong>${money(c.totalMinor)}</strong></div>`).join('')}<div class="total-row grand"><span>Total</span><span>${money(calculated.totalMinor)}</span></div><p class="muted" style="font-size:11px;margin-top:10px">${Object.keys(calculated.companies).length||0} NetSuite estimate${Object.keys(calculated.companies).length===1?'':'s'} when published.</p>`;
  }catch(error){$('#quote-totals').innerHTML=`<h3>Quote total</h3><div class="banner warning" style="margin-top:12px">${escape(error.message)}</div>`;}
}
async function editor(historical=false) {
  view.innerHTML=pageHead(quote?.number||'New quote',`${edit.jobsite?.address||''} · ${historical?'Historical revision '+quote.selected_revision:'Draft edits are retained on this device.'}`,'<button id="back-quotes">← All quotes</button>')+`${resolving?'<div class="banner warning" style="margin-bottom:16px">Review the latest draft and current taxes. Saving replaces the blocked pending revisions with this reviewed version; the old pending copies remain in device recovery history.</div>':''}${historical?'<div class="banner warning" style="margin-bottom:16px">You are viewing a saved historical revision. Downloads use this exact snapshot.</div>':''}<div class="quote-layout"><div class="stack"><section class="panel panel-pad"><form id="quote-details" class="stack"><div class="row"><h3>Customer</h3>${!historical?'<button type="button" id="link-customer" class="small">Find NetSuite customer</button>':''}</div><label>Customer or prospect name<input name="customerName" value="${escape(edit.customerName)}" required></label><div class="row"><small id="customer-link">${edit.customerId?'Linked NetSuite customer '+escape(edit.customerId):'Local prospect · link an existing customer before publishing'}</small>${edit.customerId&&!historical?'<button id="unlink-customer" type="button" class="small">Unlink</button>':''}</div><div class="grid two"><label>Contact<input name="contact" value="${escape(edit.contact)}"></label><label>Email<input name="email" type="email" value="${escape(edit.email)}"></label><label>Valid until<input name="validUntil" type="date" value="${escape(edit.validUntil)}"></label></div></form></section><section class="panel"><div class="panel-title"><h3>Items & services</h3></div><div id="quote-lines">${edit.lines.map(line=>`<article class="quote-line" data-line="${escape(line.id)}"><div class="line-top"><div>${badge(line.company)} <strong style="font-size:13px">${escape(line.sku)}</strong><p><small>${escape(line.priceSource||'Price set by rep')}</small></p></div>${historical?'':`<button class="small quiet danger" data-remove-line="${escape(line.id)}" aria-label="Remove item">✕</button>`}</div><label>Item description<input name="description" value="${escape(line.description)}" required></label><div class="line-fields"><label>Quantity<input name="quantity" inputmode="decimal" value="${escape(line.quantity)}" required></label><label>Unit rate CAD<input name="unitRate" inputmode="decimal" value="${escape(line.unitRate)}" required></label><label>Unit<input value="${escape(line.unit||'Each')}" readonly></label><label>Item subtotal CAD<output data-line-subtotal aria-live="polite">—</output><small>Before tax</small></label></div>${historical?'':`<button class="small" data-reprice="${escape(line.id)}">Refresh suggested price</button>`}</article>`).join('')||empty('Add MBBS materials, MBR rentals or MBT services.')}</div>${historical?'':itemSearchMarkup()}</section><section class="panel panel-pad stack"><h3>Revisions & NetSuite</h3><div>${(quote?.issues?.length?quote.issues:quote?.posting||[]).map(p=>`<div class="record"><strong>${p.company} · revision ${p.revision} · ${escape(p.state)}</strong>${p.error?`<p class="priority">${escape(p.error)}</p>`:''}</div>`).join('')||'<small>This revision has not been published.</small>'}</div>${quote?.estimates?.length?`<p class="muted" style="font-size:12px">${quote.estimates.map(e=>`${e.company}: ${escape(e.reference||e.netsuite_id||'Awaiting posting')}${e.closed?' (closed)':''}`).join(' · ')}</p>`:''}<div class="actions">${(quote?.versions||[]).map(v=>`<button class="small" data-version="${v.revision}">Revision ${v.revision}</button>`).join('')}</div><p class="muted" style="font-size:11px">Updates use the same linked estimates. Removing a company's last item closes its prior estimate when the new revision is published.</p></section></div><aside class="stack" style="align-content:start"><section class="panel quote-totals"><div id="quote-totals"></div><label class="quote-memo" for="quote-memo">Memo<textarea id="quote-memo" name="note" form="quote-details" maxlength="10000" placeholder="Add a memo for this quote">${escape(edit.note)}</textarea></label></section><section class="panel panel-pad stack">${!historical?'<button class="primary" id="save-quote">Save quote revision</button><button id="publish-quote">Publish to NetSuite</button>':''}<button id="pdf-combined" ${quote?'':'disabled'}>↓ Combined PDF</button><div class="actions">${Object.keys(quote?.snapshot.companies||{}).map(c=>`<button class="small" data-company-pdf="${c}">↓ ${c} PDF</button>`).join('')}</div>${quote?.posting?.some(p=>p.state==='attention')&&!historical?'<button id="retry-quote">Retry after resolving issue</button>':''}${quote?'<button id="refresh-quote" class="small">Refresh posting status</button>':''}${quote&&ctx.isAdmin()&&!historical?'<button id="reconcile-quote" class="small">Review NetSuite conflicts</button>':''}<small>PDFs contain the saved revision. A local prospect can download a draft before a NetSuite customer is linked.</small></section></aside></div>`;
  if(historical){view.querySelectorAll('#quote-details input,#quote-details textarea,#quote-lines input,#quote-memo').forEach(el=>el.disabled=true);const current=ctx.state.settings.companies;ctx.state.settings.companies=quote.snapshot.companyProfiles;totals();ctx.state.settings.companies=current;}else {totals();}
  on('#back-quotes','click',async()=>{if(!historical){readForm();await persistEdit();}await render(ctx,view);},view);
  if(!historical){on('#quote-details input,#quote-details textarea,#quote-lines input,#quote-memo','input',async()=>{readForm();totals();await persistEdit();},view);bindItemSearch(ctx,view,addItem);on('[data-remove-line]','click',async(e,b)=>{readForm();edit.lines=edit.lines.filter(l=>l.id!==b.dataset.removeLine);await persistEdit();await editor();},view);on('#link-customer','click',customerPicker,view);on('#unlink-customer','click',async()=>{readForm();edit.customerId='';await persistEdit();await editor();},view);on('[data-reprice]','click',(e,b)=>pricePicker(edit.lines.find(l=>l.id===b.dataset.reprice)),view);on('#save-quote','click',saveQuote,view);on('#publish-quote','click',publishQuote,view);}
  const pdf=async company=>{const blob=await ctx.api(`/quotes/${quote.id}/pdf?revision=${quote.selected_revision||quote.revision}${company?'&company='+company:''}`);download(blob,`${quote.number}-r${quote.selected_revision||quote.revision}-${company||'combined'}.pdf`);};
  on('#pdf-combined','click',()=>pdf(),view);on('[data-company-pdf]','click',(e,b)=>pdf(b.dataset.companyPdf),view);
  on('[data-version]','click',(e,b)=>openQuote(quote.id,Number(b.dataset.version)),view);on('#refresh-quote','click',()=>openQuote(quote.id),view);
  on('#reconcile-quote','click',async()=>{
    const result=await ctx.api(`/quotes/${quote.id}/reconciliation`);
    const el=modal('Review current NetSuite estimates',`<div class="banner warning">Review these live records before allowing a new revision to replace their contents. Converted estimates cannot be changed.</div>${result.states.map(s=>`<div class="record"><strong>${s.company} · ${escape(s.reference||'No remote estimate')}</strong><p>${s.found?money(s.totals?.totalMinor):'No record found'} · ${s.locked?'Converted':s.unmodified?'Unchanged':'Changed outside Field Sales'}</p></div>`).join('')}<label style="margin-top:16px">Reason for reconciliation<textarea id="reconcile-reason" required></textarea></label>`,'<button data-close>Cancel</button><button id="accept-remote" class="primary">Use reviewed state for next revision</button>');
