  on('#confirm-publish','click',async()=>{await ctx.api('/commands',{id:crypto.randomUUID(),kind:'quote.publish',payload:{id:quote.id,revision:quote.revision}});el.close();await openQuote(quote.id);notify('Publication queued. Each company result is tracked below.');},el);
}
async function customerPicker() {
  readForm();const el=modal('Link an existing NetSuite customer',`<form id="customer-search" class="field-row"><label>Customer name or number<input name="search" required></label><button>Search</button></form><div id="customer-results" class="catalog-results"></div><small>Creating a new NetSuite customer is handled through your existing customer setup process.</small>`);
  on('#customer-search','submit',async(event,f)=>{event.preventDefault();const items=(await ctx.read(`/customers?search=${encodeURIComponent(values(f).search)}`)).items;$('#customer-results').innerHTML=items.map(c=>`<div class="catalog-item"><div><strong>${escape(c.display_name)}</strong>${escape(c.entity_number)}</div><button class="small" data-customer="${c.id}">Link</button></div>`).join('')||empty('No active CAD customer found.');on('[data-customer]','click',async(e,b)=>{const c=items.find(i=>i.id===b.dataset.customer);edit.customerId=c.id;edit.customerName=c.display_name;edit.email=edit.email||c.email||'';await persistEdit();el.close();await editor();},el);},el);
